-- GENERATED by `wfj generate` from data/gossip/gossip-e0.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["e00046ff35ac6b95"] = { "Ho sentito parlare di voi. Windshapers. Figli ribelli dell'antica Eldre'Thalas.\r\n\nUn tempo vi avrei chiamati consanguinei, sebbene lontani. Ora non ho più nulla in comune con la stirpe elfica di quanto ne abbia con qualsiasi altra razza vivente. Di ogni creatura che respira apprezzo soltanto quanto possa servire gli scopi dei Reietti. Renditi utile al mio popolo e sarai <il/la> <benvenuto/benvenuta> nelle nostre terre.\r\n\nVa'. Esplora ⟦Undercity=Sepulcra⟧ come preferisci e goditi le sue comodità, per quel che sono. Ricorda soltanto che, nel mio dominio, nulla sfugge al mio sguardo.", "." },
  ["e005183a03a3afee"] = { "Ti insegnerò ciò che posso. Ogni lezione è un dono della Dea in persona. Usa i suoi doni con saggezza, e non vacillerai.", "." },
  ["e0054f92fb2a5a31"] = { "Certamente, {name}.\n\nGli avventurieri che l'Alba considera Venerati devono consegnare in tutto 14 insegne per accedere agli oggetti superiori. Per accedere a oggetti di potere ancora maggiore, devono consegnarne in tutto 90.\n\nPer chi è Venerato presso l'Alba, il costo degli oggetti superiori sarà piuttosto ragionevole! Il costo degli oggetti più potenti resta comunque alto.", "." },
  ["e00697f8b57d4f64"] = { "Li hai già trovati, {name}? I capi della ⟦Searing Blade=Lama Rovente⟧.\n\nSapevo che il ⟦Shadow Council=Concilio dell'Ombra⟧ cercava di strapparmi Orgrimmar e tutta l'⟦Horde=Orda⟧, ma non mi ero reso conto di quanto in fretta fossero riusciti a infiltrarsi in città. Quante braccia ha questa bestia... possiamo tagliarle fino allo sfinimento, ma non saremo più avanti di quando abbiamo cominciato. Dovrò chiedere alle mie spie di raddoppiare gli sforzi.", "." },
  ["e00dfbafbe8916ea"] = { "Gimlok, non andare a sporcarti tutti i vestiti.", "." },
  ["e0152b4a996cdf1c"] = { "Lascia che ti addestri nelle vie del cacciatore.", "." },
  ["e0238426ebf72fdb"] = { "Odio questa parte del mio lavoro. Oh, ⟦Duskwood=Boscovespro⟧, sii gentile con il povero Antonio.", "." },
  ["e02b2167bffbd654"] = { "Non troverai mai le lame gemelle di Sul.", "." },
  ["e02e6f6131d0aaad"] = { "Kel'Thuzad si è impegnato a fondo nel tentativo di ricomporre il bastone. Un tempo i pezzi erano sparsi per tutto il mondo, da Kalimdor ai ⟦South Seas=Mari del Sud⟧. A un certo punto ne ho posseduti venti, finché i servitori di Kel'Thuzad non me li hanno rubati. È per questo che sono qui.", "." },
  ["e02f25371bf5e2b1"] = { "M-m-mi senti! Sia l-l-lodato il b-b-bilancio!\n\nNon sono davvero un p-p-pupazzo di neve: mi c-c-chiamo Sacks e l-l-lavoro per la f-f-filiale di ⟦Ironforge=Forgiardente⟧ della Masseria Buongusto... Mi hanno m-m-mandato qui a cercare un p-p-pacco scomparso, quando sono stato attaccato da una c-c-creatura che non avevo mai visto p-p-prima!\n\nChe f-f-freddo...", "." },
  ["e03239dab4a2c997"] = { "Era ora che arrivasse qualcuno. Perché ci hai messo tanto? Ah, lascia perdere. Coprimi, soldato. Devo tornare alla base!", "." },
  ["e0478c84606ee4b3"] = { "Zephras è in grave pericolo. Gli spiriti elementali del vento che tante migliaia di anni fa ci portarono qui, a ⟦Skywall=Celaria⟧, ci hanno abbandonati, lasciandoci vulnerabili in questo regno instabile. La nostra società, un tempo fiorente, si estendeva su diversi santuari insulari nel nostro angolo di ⟦Skywall=Celaria⟧, ma ora non sappiamo nemmeno se esistano altri shen'dorei fuori da questa piccola isola.\r\n\nLa situazione è disperata, ma l'High Order è determinato ad affrontare questa sfida.", "." },
  ["e04a327e9c9ac95e"] = { "%s si gratta la gola.", "." },
  ["e056cb6899e6501a"] = { "Salute, {name}. Se mi porti pietre necrotiche prese agli invasori non morti, posso darti accesso alle scorte dell'⟦Argent Dawn=Alba d'Argento⟧.", "." },
  ["e05c22a9a651037e"] = { "Hai distrutto troppo del mio lavoro! Preparati a raggiungerli nel Nether!", "." },
  ["e05c393349c92afe"] = { "Voglio vedere lo scheletro del drago nella grande biblioteca.", "." },
  ["e064da900d0b2e4a"] = { "Il vilsegugio si avvicina! State in guardia!", "." },
  ["e06b3d0ee087f3c8"] = { "Ciao, questo è il mio testo.", "." },
  ["e070ed89e92a320c"] = { "Lok'tar, {class}, ho informazioni importanti! Ad ⟦Ahn'Qiraj=Ahn'qiraj⟧ sta per scoppiare una guerra e dobbiamo prepararci. Sono qui per raccogliere tutto il cuoio spesso su cui riesco a mettere le mani. Al momento ne abbiamo $2070w, ma il Capoguerra mi ha incaricato di raccoglierne $2071w. Come vedi, sono un po' a corto.", "." },
  ["e07144641c1285e3"] = { "Ah, <uno/una> <Stregone/Strega> come me, che ha dato prova del proprio valore, almeno in qualche misura.\n\nÈ un piacere fare la tua conoscenza. Mi chiamo ⟦Menara Voidrender=Menara Squarciavuoto⟧... e non senza una buona ragione.\n\nSembri abbastanza potente ed erudit<o/a> perché altri strumenti... strumenti più potenti... siano ben accetti e non affidati in modo sconsiderato. Se è così, continua a parlare con me. Altrimenti, beh, conosci la strada per tornare al molo e poi giù nell'oceano.", "." },
  ["e072387cbbef9e7b"] = { "Se desideri visitare l'altura del Profanatore, non devi far altro che chiedere. Posso trasportare te e i tuoi compagni.", "." },
  ["e077635091b54305"] = { "Sappiano tutti che {name}, {class} dell'⟦Horde=Orda⟧, ha conquistato il rispetto imperituro del Capoguerra. Ha condotto con grande diplomazia i rapporti con il ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧ e ha compiuto per loro azioni valorose a nostro nome. Ha fatto molto più di quanto il dovere richiedesse. Tre urrà per {name}, <un/una> <vero/vera> <eroe/eroina> dell'⟦Horde=Orda⟧!", "." },
  ["e07dc839a73424e3"] = { "Va' alla ⟦Shady Rest Inn=Locanda Ombracalma⟧ e segui le tracce. Scopri dove portano e torna a riferirmi.", "." },
  ["e0892f73337441dc"] = { "La vendetta sarà mia.", "." },
  ["e089f751ad4c86e6"] = { "Voglio addestrarmi.", "." },
  ["e08b0bde265c1dec"] = { "Tanti scaffali, così poco tempo...", "." },
  ["e08cd4a7b5b7f443"] = { "Grazie, mi hai salvato la vita!", "." },
  ["e08fa9da416384d7"] = { "Non credo che sia abbastanza forte.", "." },
  ["e08fd1f1b38c5a29"] = { "Ah, per visitarne uno devi salire sulle grandi alture del ⟦Thunder Bluff=Picco del Tuono⟧. Segui il sentiero a nord che esce dal ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. Ai piedi delle alture c'è un ascensore che ti porterà in cima. Quando arrivi, chiedi altre indicazioni a uno dei Guardiani del Picco.", "." },
  ["e0969b6edf3f5d9e"] = { "Arrendetevi e vi lasciamo vivi, miscredenti! Posate l'armi e marciate!", "." },
  ["e09f39de91aa7bb1"] = { "Ho un sacco di ottime ricette da farti vedere, e a prezzi scontati!", "." },
  ["e0a141a60a08d799"] = { "Dunque cerchi Niby per apprendere i segreti dell'evocazione di un servitore infernale dal Nether.\n\nSilenzio! Niby sa tutto!\n\nNiby non si separa tanto in fretta da un tale sapere. Prima devi aiutare Niby in un compito molto importante.", "." },
  ["e0a3390cbe52a438"] = { "Il maestro d'armi", "." },
  ["e0a432e952d1b785"] = { "*sospiro* È quasi ora di controllare di nuovo il cimitero... Torno tra qualche minuto.", "." },
  ["e0a7303cc7bab5d9"] = { "Ah, il buon vecchio ⟦Brandur Ironhammer=Brandur Fermartello⟧. Non c'è dubbio che ti darà la guida che cerchi, <ragazzo/ragazza>. Lo troverai nella Hall of Mysteries, a nord dei cancelli di ⟦Ironforge=Forgiardente⟧.", "." },
  ["e0c00f9b8ed128c4"] = { "Il capitano Galvangar è il fidato braccio destro di ⟦Drek'Thar=Drek'thar⟧. Guida le forze dell'⟦Horde=Orda⟧ dal ⟦Iceblood Garrison=Presidio di Brinarossa⟧, nella parte meridionale del ⟦Field of Strife=Pian della Discordia⟧.\n\nAl momento il capitano Galvangar si trova nel ⟦Iceblood Garrison=Presidio di Brinarossa⟧.", "." },
  ["e0c8c93db2793f92"] = { "Ti maledico, mortale.", "." },
  ["e0c93b079c13fd4d"] = { "Porterò quel segnalatore al cratere senza un graffio, Guse. Puoi contare su di me!", "." },
  ["e0cfad60591d42e1"] = { "All'attacco!!", "." },
  ["e0d10f8d98aa651e"] = { "Mettiti a correre!", "." },
  ["e0d648c0864c6a9d"] = { "Ultimamente il flusso della magia è stato turbato. Ho sentito che persino i maghi di Dalaran sono perplessi. Questo disturbo è di natura arcana, o sono gli elementi stessi a essere in subbuglio?", "." },
  ["e0dafdaacb97c2f0"] = { "Fiori, semi e cose del genere? È il campo di Reyna Stonebranch. La trovi a curare le sue piante all'Ironforge Physician, sul lato sud della ⟦Great Forge=Grande Forgia⟧.", "." },
  ["e0e528fb821d09a9"] = { "Certo, Paige. Ma fai piano.", "." },
  ["e0ee4195f9e25ebe"] = { "Piacere di conoscerti. Posso aiutarti?", "." },
  ["e0f784d50a83186d"] = { "Il Brandi-cosa? Ah, il BRANDICENERE? Mai sentito... Cosa? Smettila di seccarmi!", "." },
  ["e0f88a1ce02eed08"] = { "A quanto pare hai già trovato l'amore. Puoi darmi un pegno d'amore, ma non ti darò niente di bello. Aspetto qualcuno di speciale.", "." },
  ["e0fc3c79cdb42f03"] = { "Addestro e guido i giovani cacciatori nelle tradizioni tramandate da molte generazioni.", "." },
})
